import React, { useState, useEffect } from 'react';
import { C, navLinks } from '../data';
import Logo from './Logo';

function MenuIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{width:24,height:24}}><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="18" x2="21" y2="18"/></svg>;
}
function XIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{width:24,height:24}}><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>;
}

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', fn);
    return () => window.removeEventListener('scroll', fn);
  }, []);

  const scrollTo = (id) => {
    setOpen(false);
    document.getElementById(id.toLowerCase().replace(/ /g, '-'))?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <nav
      style={{
        background: scrolled ? 'rgba(255,255,255,0.97)' : 'transparent',
        boxShadow: scrolled ? '0 2px 20px rgba(26,58,143,0.10)' : 'none',
        backdropFilter: scrolled ? 'blur(12px)' : 'none',
        transition: 'all 0.35s ease',
        position: 'fixed', top: 0, left: 0, right: 0, zIndex: 50,
      }}
    >
      <div style={{ maxWidth: 1280, margin: '0 auto', padding: '16px 24px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, cursor: 'pointer' }} onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>
          <Logo size={44} />
          <span style={{ fontWeight: 700, fontSize: 20, color: scrolled ? C.blue : C.white, fontFamily: "'Playfair Display', Georgia, serif", letterSpacing: '-0.5px' }}>
            TutorBridge
          </span>
        </div>

        {/* Desktop Nav */}
        <div className="desktop-nav" style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
          {navLinks.map((l) => (
            <button
              key={l}
              onClick={() => scrollTo(l)}
              style={{
                padding: '8px 16px', borderRadius: 10, fontSize: 14, fontWeight: 500,
                color: scrolled ? C.text : C.white, background: 'none', border: 'none',
                cursor: 'pointer', transition: 'all 0.2s',
              }}
              onMouseEnter={e => e.target.style.background = C.bluePale}
              onMouseLeave={e => e.target.style.background = 'none'}
            >
              {l}
            </button>
          ))}
        </div>

        <div className="desktop-nav" style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <button
            onClick={() => scrollTo('Contact')}
            style={{
              padding: '10px 20px', borderRadius: 12, fontSize: 13, fontWeight: 600,
              border: `2px solid ${C.gold}`, color: scrolled ? C.blue : C.white, background: 'none',
              cursor: 'pointer', transition: 'all 0.2s',
            }}
          >
            Join as Tutor
          </button>
          <button
            onClick={() => scrollTo('Contact')}
            style={{
              padding: '10px 20px', borderRadius: 12, fontSize: 13, fontWeight: 600,
              background: C.gold, color: C.blue, border: 'none',
              cursor: 'pointer', transition: 'all 0.2s',
              boxShadow: '0 4px 14px rgba(245,166,35,0.35)',
            }}
          >
            Find a Tutor
          </button>
        </div>

        {/* Mobile Toggle */}
        <button className="mobile-menu-btn" onClick={() => setOpen(!open)} style={{ background: 'none', border: 'none', color: scrolled ? C.blue : C.white, display: 'none' }}>
          {open ? <XIcon /> : <MenuIcon />}
        </button>
      </div>

      {/* Mobile Menu */}
      {open && (
        <div style={{ background: C.white, borderTop: `1px solid ${C.border}`, padding: '16px 24px' }}>
          {navLinks.map((l) => (
            <button key={l} onClick={() => scrollTo(l)} style={{ display: 'block', width: '100%', textAlign: 'left', padding: '12px 0', fontSize: 14, fontWeight: 500, color: C.text, background: 'none', border: 'none', borderBottom: `1px solid ${C.border}`, cursor: 'pointer' }}>
              {l}
            </button>
          ))}
          <div style={{ display: 'flex', gap: 12, marginTop: 16 }}>
            <button onClick={() => scrollTo('Contact')} style={{ flex: 1, padding: '10px', borderRadius: 12, fontSize: 13, fontWeight: 600, border: `2px solid ${C.gold}`, color: C.blue, background: 'none', cursor: 'pointer' }}>Join as Tutor</button>
            <button onClick={() => scrollTo('Contact')} style={{ flex: 1, padding: '10px', borderRadius: 12, fontSize: 13, fontWeight: 600, background: C.gold, color: C.blue, border: 'none', cursor: 'pointer' }}>Find a Tutor</button>
          </div>
        </div>
      )}

      <style>{`
        @media (max-width: 1024px) {
          .desktop-nav { display: none !important; }
          .mobile-menu-btn { display: block !important; }
        }
      `}</style>
    </nav>
  );
}
